/* SPDX-License-Identifier: GPL-3.0-only
 * FM-XY STYLE gate: share delayed note events between physical keys.
 * Pure fixed-memory primitive; NOT connected to Felucca audio yet.
 *
 * Only emit a note-on for the first physical owner of a pitch, and
 * note-off for the last. Call only with the events generated by
 * fmxy_style_process/up/panic; external MIDI owners remain Felucca's.
 * Never reset during playback: panic the STYLE queue first.
 */
#ifndef FMXY_STYLE_GATE_H
#define FMXY_STYLE_GATE_H
#include <stdint.h>

typedef void (*fmxy_style_gate_emit_t)(uint8_t note, uint8_t on, void *ctx);
typedef struct {
    uint8_t references[128]; /* <= 27 physical keys per pitch */
    fmxy_style_gate_emit_t emit;
    void *ctx;
} fmxy_style_gate_t;

static inline void fmxy_style_gate_init(fmxy_style_gate_t *g,
                                         fmxy_style_gate_emit_t emit, void *ctx)
{
    uint32_t i;
    if (!g) return;
    for (i = 0; i < 128u; ++i) g->references[i] = 0;
    g->emit = emit;
    g->ctx = ctx;
}

/* Adapter for fmxy_style_emit_t. The key is already owned by the queue;
 * its validated per-key note list guarantees only one ON/OFF per pitch. */
static inline void fmxy_style_gate_event(uint8_t key, uint8_t note,
                                         uint8_t on, void *context)
{
    fmxy_style_gate_t *g = (fmxy_style_gate_t *)context;
    uint8_t *refs;
    (void)key;
    if (!g || !g->emit || note > 127u) return;
    refs = &g->references[note];
    if (on) {
        if (*refs == UINT8_MAX) return; /* defensive; max is 27 */
        if ((*refs)++ == 0)
            g->emit(note, 1, g->ctx);
    } else if (*refs && --(*refs) == 0) {
        g->emit(note, 0, g->ctx);
    }
}
#endif
